//Using jasmine
(function(outputs, steps, params, stepResult, assertEqual) {
	var ohsmUtils = new x_hccc_hoc_ohs.HoCOHSMUtils();
	var recordSysId = steps('a6690b1a1b33e994893442a7bc4bcbe6').record_id;

	var caseGr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
    caseGr.get(recordSysId);

	describe('using a glideRecord', function() {
		var time = ohsmUtils.getTime(caseGr);
		it('should return timeZone adjusted formatted time of [date_and_time_of_occurrence]', function() {
			var time = ohsmUtils.getTime(caseGr);
			expect(time).toBe("1532");
		});
		describe('and a column', function() {
			var time2 = ohsmUtils.getTime(caseGr, 'inc_date_time');
			it('should return timeZone adjusted formatted time of the passed column ([inc_date_time])', function() {
				expect(time2).toBe("1121");
			});

			describe('that does NOT exist', function() {
				it('should throw an exception', function() {
					expect(function(){
						ohsmUtils.getTime(caseGr, 'jsadjsafdgonsafge');
					}).toThrow();
				});
			});
		});
	});

	describe("Using a string", function (){
		it("should return timeZone adjusted formatted time of the string", function(){
			var fieldValue = caseGr.getValue('date_and_time_of_occurrence'); //this is the time in UTC
			var fieldDisplayValue = caseGr.getDisplayValue('date_and_time_of_occurrence'); //This is the time adjusted (getTime already adjust so this should fail)

			var time = ohsmUtils.getTime(fieldValue); //using UTC
			var time2 = ohsmUtils.getTime(fieldDisplayValue); //Using adjusted

			expect(time).toBe("1532"); //should show the right thing
			expect(time2).not.toBe("1532"); //should not show the right thing
		});

		it("should fail when not formatted correctly", function(){
			expect(function(){ //toThrow expects a function, not a function call
				ohsmUtils.getTime("Lorem ipsum dolor sit amet");
			}).toThrow();
		});
	});

	describe("Using non supported inputs", function (){
		it("should fail", function(){
			expect(function(){ //toThrow expects a function, not a function call
				ohsmUtils.getTime({foo: "foo", bar: "bar"});
			}).toThrow();
			expect(function(){ //toThrow expects a function, not a function call
				ohsmUtils.getTime(null);
			}).toThrow();
			expect(function(){ //toThrow expects a function, not a function call
				ohsmUtils.getTime(true);
			}).toThrow();
			expect(function(){ //toThrow expects a function, not a function call
				ohsmUtils.getTime([1,2,3,4]);
			}).toThrow();
			expect(function(){ //toThrow expects a function, not a function call
				ohsmUtils.getTime(anUndefinedVariable);
			}).toThrow();
		});
	});
})(outputs, steps, params, stepResult, assertEqual);
jasmine.getEnv().execute();
